public class InefficientWeightDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
        "Suspicious0dp",
        "Suspicious 0dp dimension",
        "Using 0dp as the width in a horizontal `LinearLayout` with weights is a useful trick ... However, if you use 0dp for the opposite dimension, the view will be invisible. ...",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(InefficientWeightDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() { return Collections.singletonList(TAG_LINEAR_LAYOUT); }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean horizontal = orientation == null || orientation.isEmpty() || VALUE_HORIZONTAL.equals(orientation);
        // Actually default orientation is horizontal.
        boolean vertical = VALUE_VERTICAL.equals(orientation);

        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE && child instanceof Element) {
                Element childEl = (Element) child;
                String width = childEl.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH);
                String height = childEl.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT);
                String weightStr = childEl.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
                boolean hasWeight = weightStr != null && !weightStr.isEmpty();
                double weight = 0;
                if (hasWeight) { try parse weightStr; if invalid maybe 0? }
                boolean positiveWeight = hasWeight && weight > 0;

                if (horizontal) {
                    if (isZeroDimension(width)) {
                        // OK if positive weight, otherwise suspicious
                        if (!positiveWeight) {
                            report(context, childEl, ATTR_LAYOUT_WIDTH, width);
                        }
                    } else if (isZeroDimension(height)) {
                        // suspicious (opposite dimension) regardless of weight? if height 0dp view invisible. If weight>0 it's particularly suspicious. Could always flag.
                        report(context, childEl, ATTR_LAYOUT_HEIGHT, height);
                    }
                } else if (vertical) {
                    if (isZeroDimension(height)) {
                        if (!positiveWeight) {
                            report(context, childEl, ATTR_LAYOUT_HEIGHT, height);
                        }
                    } else if (isZeroDimension(width)) {
                        report(context, childEl, ATTR_LAYOUT_WIDTH, width);
                    }
                }
            }
            child = child.getNextSibling();
        }
    }

    private static boolean isZeroDimension(String value) { ... }

    private static void report(XmlContext context, Element element, String attributeName, String value) {
        // Use report on attribute location.
        Attr attr = element.getAttributeNodeNS(ANDROID_URI, attributeName);
        Location location = attr != null ? context.getLocation(attr) : context.getLocation(element);
        context.report(ISSUE, element, location, "Suspicious 0dp dimension: the view may be invisible because `" + attributeName + "` is set to `" + value + "`");
    }
}

