    }
    if (i == 0) return false;
    String num = s.substring(0, i);
    try {
        if (Float.parseFloat(num) != 0f) return false;
    } catch (NumberFormatException e) { return false; }
    String unit = s.substring(i).trim();
    return unit.isEmpty() || unit.equalsIgnoreCase("dp") || unit.equalsIgnoreCase("dip") || unit.equalsIgnoreCase("sp") || unit.equalsIgnoreCase("px") || unit.equalsIgnoreCase("pt") || unit.equalsIgnoreCase("mm") || unit.equalsIgnoreCase("in");
}
